fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both vectors have the same length, we can safely zip them
    // and compare elements pairwise.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x != y)
     .collect()
}